input.content:
# Ana sayfa yamasi:
#  1) Kelime markasinin "oo" halkalarini canlandirir (radar + cekirdek).
#     Koordinatlar marka-yazisi-koyu.png uzerinden OLCULDU:
#       o1 merkez (460, 227), o2 merkez (729, 227)
#       dis yaricap 119.5, ic bosluk yaricapi 72.5, viewBox 1200x348
#  2) Logo isaretini buyuk bir filigran olarak turuncu alana yerlestirir.
#  3) Telefon maketlerindeki mekanlari Istanbul'dakilerle degistirir.
#     Hepsi veritabaninda GERCEKTEN kayitli; ilce bilgisi kendi kaydindan.

import os
import re
import sys

SCRATCH = os.path.dirname(os.path.abspath(__file__))
HTML = os.path.join(SCRATCH, "slooin-ana-sayfa.html")

with open(HTML, encoding="utf-8") as f:
    icerik = f.read()


def degistir(eski, yeni, adet=1):
    global icerik
    bulunan = icerik.count(eski)
    if bulunan < adet:
        sys.exit("HATA: bulunamadi (%d/%d): %s" % (bulunan, adet, eski[:70]))
    icerik = icerik.replace(eski, yeni, adet)


# ------------------------------------------------------------------
# 1) Isaret data URI'sini yakala (filigranda yeniden kullanilacak)
# ------------------------------------------------------------------
m = re.search(r'<img class="isaret" src="(data:image/png;base64,[^"]+)"', icerik)
if not m:
    sys.exit("HATA: isaret data URI bulunamadi")
isaret_uri = m.group(1)

# ------------------------------------------------------------------
# 2) Kelime markasini lockup'a sar + SVG katmani ekle
# ------------------------------------------------------------------
m = re.search(r'<img class="kelime-markasi"[^>]*>', icerik)
if not m:
    sys.exit("HATA: kelime markasi img bulunamadi")

lockup = (
    '<div class="marka-lockup">\n'
    "        " + m.group(0) + "\n"
    '        <svg viewBox="0 0 1200 348" aria-hidden="true" focusable="false">\n'
    '          <circle class="halka" cx="460" cy="227" r="119.5"></circle>\n'
    '          <circle class="halka gecikmeli" cx="460" cy="227" r="119.5"></circle>\n'
    '          <circle class="cekirdek" cx="729" cy="227" r="46"></circle>\n'
    "        </svg>\n"
    "      </div>"
)
degistir(m.group(0), lockup)

# ------------------------------------------------------------------
# 3) Filigran: logo isareti, turuncu alanin sol altindan tasar
# ------------------------------------------------------------------
degistir(
    '<span class="dalga" aria-hidden="true"></span>',
    '<span class="dalga" aria-hidden="true"></span>\n'
    '  <img class="filigran" src="%s" alt="" aria-hidden="true">' % isaret_uri,
)

# ------------------------------------------------------------------
# 4) CSS
# ------------------------------------------------------------------
css = """
  /* ---- marka lockup: "oo" halkalari canli ---- */

  .marka-lockup {
    position: relative;
    display: block;
    width: clamp(240px, 31vw, 356px);
  }

  .marka-lockup .kelime-markasi { width: 100%; height: auto; display: block; }

  .marka-lockup svg {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    overflow: visible;
    pointer-events: none;
  }

  /* Sol "o": yayilan radar halkasi - orada bir yer canli. */
  .halka {
    fill: none;
    stroke: var(--turuncu);
    stroke-width: 9;
    opacity: 0.5;
    transform-origin: 460px 227px;
    animation: yayil 2.9s cubic-bezier(0.2, 0.6, 0.3, 1) infinite;
  }

  .halka.gecikmeli { animation-delay: 1.45s; }

  @keyframes yayil {
    0%   { transform: scale(1);    opacity: 0.75; stroke-width: 11; }
    70%  { opacity: 0.16; }
    100% { transform: scale(1.72); opacity: 0;    stroke-width: 2; }
  }

  /* Sag "o": icinde duran nokta - orada birisi var. */
  .cekirdek {
    fill: var(--turuncu);
    transform-origin: 729px 227px;
    animation: nefes 2.9s ease-in-out infinite;
  }

  @keyframes nefes {
    0%, 100% { transform: scale(1); }
    50%      { transform: scale(1.13); }
  }

  /* ---- logo filigrani ---- */

  .filigran {
    position: absolute;
    left: -7%;
    bottom: -16%;
    width: clamp(300px, 40vw, 580px);
    opacity: 0.085;
    pointer-events: none;
    z-index: 0;
  }

  @media (max-width: 899px) {
    .filigran { left: auto; right: -18%; bottom: auto; top: -8%; width: 320px; }
  }
"""
degistir("\n  @media (prefers-reduced-motion: reduce) {", css + "\n  @media (prefers-reduced-motion: reduce) {")

# Slogan yanindaki isaret buyusun
degistir(
    "  .isaret { width: 38px; height: 38px; flex: none; display: block; }",
    "  .isaret { width: 54px; height: 54px; flex: none; display: block; }",
)

# ------------------------------------------------------------------
# 5) Istanbul mekanlari (hepsi veritabaninda kayitli, ilce kendi kaydindan)
# ------------------------------------------------------------------
liste = [
    ("Kültürpark", "Osmangazi, Bursa", "Galata Kulesi", "Beyoğlu, İstanbul"),
    ("Merinos Parkı", "Osmangazi, Bursa", "Emirgan Korusu", "Sarıyer, İstanbul"),
    ("Nilüfer Sahili", "Nilüfer, Bursa", "Yıldız Parkı", "Beşiktaş, İstanbul"),
    ("Setbaşı", "Yıldırım, Bursa", "Gülhane Park", "Fatih, İstanbul"),
]

for eski_ad, eski_yer, yeni_ad, yeni_yer in liste:
    degistir(
        '<div class="bilgi"><div class="ad">%s</div><div class="yer">%s</div></div>'
        % (eski_ad, eski_yer),
        '<div class="bilgi"><div class="ad">%s</div><div class="yer">%s</div></div>'
        % (yeni_ad, yeni_yer),
    )

# Arka telefondaki mekan sayfasi - listedekiyle ayni yer (Galata'ya dokunulmus hali)
degistir('<div class="ad">Kültürpark</div>', '<div class="ad">Galata Kulesi</div>')
degistir('<div class="yer">Osmangazi, Bursa</div>', '<div class="yer">Beyoğlu, İstanbul</div>')

with open(HTML, "w", encoding="utf-8") as f:
    f.write(icerik)

print("Yama uygulandi. HTML: %.1f KB" % (os.path.getsize(HTML) / 1024))

